import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateCustomerAddressesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateCustomerAddressesWorkflow(req.scope)
    .run({
      input: {
        selector: {
          customer_id: "123"
        },
        update: {
          first_name: "John"
        },
        additional_data: {
          crm_id: "123"
        }
      }
    })

  res.send(result)
}

